<script setup>
import { hasPermission } from '../../utils/permissions'
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import BaseButton from '../../components/ui/BaseButton.vue'
import { customerProfileService } from '../../services/customerProfileService'

const route = useRoute()
const router = useRouter()
const record = ref(null)
const loading = ref(false)
const errorMessage = ref('')
const activeTab = ref('overview')
const fullName = computed(() => [record.value?.first_name, record.value?.middle_name, record.value?.last_name].filter(Boolean).join(' ') || 'Customer profile')
const initials = computed(() => [record.value?.first_name, record.value?.last_name].filter(Boolean).map(part => part.charAt(0).toUpperCase()).join('') || 'C')
function display(value) { return value === null || value === undefined || String(value).trim() === '' ? '—' : value }
function formatDate(value) { if (!value) return '—'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' }).format(date) }
async function loadRecord() {
  loading.value = true
  errorMessage.value = ''
  try { const response = await customerProfileService.get(route.params.id); record.value = response?.data?.data || response?.data || response }
  catch (error) { errorMessage.value = error?.message || 'Unable to load customer profile.' }
  finally { loading.value = false }
}
onMounted(loadRecord)
</script>
<template>
  <section class="module-page customer-detail-page">
    <div class="module-page-intro detail-page-heading"><div><p class="eyebrow">CUSTOMER MANAGEMENT</p><h2>Customer profile</h2></div><div class="detail-actions"><BaseButton variant="secondary" @click="router.push('/customers')">← Back to customers</BaseButton><BaseButton v-if="hasPermission('customer-profiles:update')" :disabled="!record || loading" @click="router.push(`/customers/${route.params.id}/edit`)">Edit customer</BaseButton></div></div>
    <p v-if="loading" class="module-description detail-state">Loading customer profile…</p>
    <section v-else-if="errorMessage" class="module-panel detail-state" role="alert"><p>{{ errorMessage }}</p><BaseButton variant="secondary" @click="loadRecord">Try again</BaseButton></section>
    <template v-else-if="record">
      <section class="customer-profile-hero"><div class="customer-avatar">{{ initials }}</div><div class="customer-hero-copy"><h3>{{ fullName }}</h3><div class="customer-contact-line"><span v-if="record.email">{{ record.email }}</span><span v-if="record.email && record.phone" class="contact-separator">·</span><span v-if="record.phone">{{ record.phone }}</span></div></div></section>
      <nav class="customer-detail-tabs" aria-label="Customer detail sections" role="tablist"><button type="button" role="tab" :aria-selected="activeTab === 'overview'" :class="{ active: activeTab === 'overview' }" @click="activeTab = 'overview'">Overview</button><button type="button" role="tab" :aria-selected="activeTab === 'address'" :class="{ active: activeTab === 'address' }" @click="activeTab = 'address'">Address</button><button type="button" role="tab" :aria-selected="activeTab === 'branch'" :class="{ active: activeTab === 'branch' }" @click="activeTab = 'branch'">Branch</button></nav>
      <div v-if="activeTab === 'overview'" class="customer-detail-sections">
        <section class="module-panel customer-detail-card"><div class="customer-section-heading"><span class="customer-section-icon">01</span><div><h3>Customer information</h3></div></div><dl class="customer-detail-grid"><div><dt>First name</dt><dd>{{ display(record.first_name) }}</dd></div><div><dt>Middle name</dt><dd>{{ display(record.middle_name) }}</dd></div><div><dt>Last name</dt><dd>{{ display(record.last_name) }}</dd></div></dl></section>
        <section class="module-panel customer-detail-card"><div class="customer-section-heading"><span class="customer-section-icon">02</span><div><h3>Contact information</h3></div></div><dl class="customer-detail-grid"><div><dt>Email address</dt><dd>{{ display(record.email) }}</dd></div><div><dt>Phone number</dt><dd>{{ display(record.phone) }}</dd></div></dl></section>
      </div>
      <div v-else-if="activeTab === 'address'" class="customer-detail-sections address-tab"><section class="module-panel customer-detail-card"><div class="customer-section-heading"><span class="customer-section-icon">03</span><div><h3>Address</h3></div></div><dl class="customer-detail-grid"><div class="detail-span-two"><dt>Street address</dt><dd>{{ [record.address_line1, record.address_line2].filter(Boolean).join(', ') || '—' }}</dd></div><div><dt>City</dt><dd>{{ display(record.city) }}</dd></div><div><dt>State / province</dt><dd>{{ display(record.state_province) }}</dd></div><div><dt>Postal code</dt><dd>{{ display(record.postal_code) }}</dd></div><div><dt>Country</dt><dd>{{ display(record.country) }}</dd></div></dl></section></div>
      <div v-else-if="activeTab === 'branch'" class="customer-detail-sections address-tab"><section class="module-panel customer-detail-card"><div class="customer-section-heading"><span class="customer-section-icon">04</span><div><h3>Branch assignment</h3></div></div><dl class="customer-detail-grid"><div><dt>Assigned branch</dt><dd>{{ display(record.branch?.branch_name || record.branch?.branch_code || record.branch_id) }}</dd></div><div><dt>Branch code</dt><dd>{{ display(record.branch?.branch_code) }}</dd></div><div><dt>Branch location</dt><dd>{{ display(record.branch?.location || record.branch?.address) }}</dd></div><div><dt>Created by</dt><dd>{{ [record.maker?.first_name, record.maker?.last_name].filter(Boolean).join(' ') || display(record.maker_id) }}</dd></div><div><dt>Maker email</dt><dd>{{ display(record.maker?.email) }}</dd></div></dl></section></div>
      <section class="customer-record-footer"><div><span>Last updated</span><strong>{{ formatDate(record.updated_at) }}</strong></div><div><span>Record status</span><strong>{{ record.is_deleted ? 'Deleted' : 'Active record' }}</strong></div></section>
    </template>
  </section>
</template>
<style scoped>
.customer-detail-page{gap:22px}.detail-page-heading{align-items:center;gap:18px}.eyebrow{margin:0 0 6px;color:var(--brand-base-color,#4263c7);font-size:.7rem;font-weight:750;letter-spacing:.12em}.detail-actions{display:flex;gap:9px;flex-wrap:wrap}.detail-state{padding:22px}.customer-profile-hero{display:flex;align-items:center;gap:18px;padding:24px 28px;border:1px solid #dfe7f5;border-radius:18px;background:linear-gradient(115deg,#f2f6ff 0%,#f8faff 54%,#f1f8f7 100%);box-shadow:0 8px 24px rgba(35,57,99,.045)}.customer-avatar{display:flex;align-items:center;justify-content:center;flex:0 0 54px;width:54px;height:54px;border-radius:17px;background:#dfe8ff;color:#3154a3;font-size:1.05rem;font-weight:750}.customer-hero-copy{min-width:0;flex:1}.customer-hero-copy h3{margin:0;color:#202d43;font-size:clamp(1.3rem,2vw,1.65rem);letter-spacing:-.025em}.customer-contact-line{display:flex;gap:8px;flex-wrap:wrap;margin:7px 0 0;color:#647187;font-size:.9rem;overflow-wrap:anywhere}.contact-separator{color:#a0aabb}.customer-detail-tabs{display:flex;align-items:center;gap:0;width:100%;border-bottom:1px solid var(--border-color,#d9dde5);overflow-x:auto}.customer-detail-tabs button{position:relative;flex:0 0 auto;padding:12px 17px;border:0;border-bottom:2px solid transparent;margin-bottom:-1px;background:transparent;color:var(--text-muted-color,#667085);font:inherit;font-size:.84rem;font-weight:700;cursor:pointer}.customer-detail-tabs button.active{border-bottom-color:var(--brand-base-color,#435fb0);color:var(--brand-base-color,#435fb0)}.customer-detail-sections{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.address-tab{grid-template-columns:minmax(0,1fr)}.customer-detail-card{padding:22px;min-width:0}.customer-section-heading{display:flex;align-items:center;gap:12px;padding-bottom:18px;border-bottom:1px solid #edf0f5}.customer-section-icon{display:inline-flex;align-items:center;justify-content:center;flex:0 0 38px;width:38px;height:38px;border-radius:12px;background:#f0f4fc;color:#4662a6;font-size:.75rem;font-weight:800}.customer-section-heading h3{margin:0;font-size:1rem;color:var(--text-primary,#273449)}.customer-detail-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px 18px;margin:0;padding-top:20px}.customer-detail-grid>div{min-width:0}.customer-detail-grid dt{margin-bottom:6px;color:#7b8494;font-size:.76rem;font-weight:550}.customer-detail-grid dd{margin:0;color:#273449;font-size:.9rem;font-weight:600;overflow-wrap:anywhere}.detail-span-two{grid-column:1/-1}.customer-record-footer{display:flex;gap:24px;flex-wrap:wrap;padding:17px 22px;border:1px solid #e8ecf2;border-radius:14px;background:#fbfcfe}.customer-record-footer div{display:flex;flex-direction:column;gap:5px}.customer-record-footer span{color:#7b8494;font-size:.75rem}.customer-record-footer strong{color:#3d4a5f;font-size:.82rem;font-weight:600}@media(max-width:760px){.customer-detail-sections{grid-template-columns:1fr}.customer-detail-tabs{width:100%}.customer-detail-tabs button{padding:11px 12px}.customer-profile-hero{padding:20px;gap:15px}}@media(max-width:520px){.detail-page-heading{align-items:flex-start;flex-direction:column}.customer-detail-card{padding:17px}.customer-detail-grid{gap:17px 12px}}
</style>
